close all; clear all; clc;%% --- Planta ---K   = 0.4667;tau = 412;G   = tf(K, [tau 1]);%% --- PI-IMC ---lambda = tau * 0.46;   % <-- ajuste aquiKp = tau / (K * lambda);Ti = tau;Ki = Kp / Ti;C  = tf([Kp Ki], [1 0]);fprintf('Kp = %.4f  |  Ti = %.1fs  |  lambda = %.1fs\n', Kp, Ti, lambda)%% --- Malha fechada ---T_mf = feedback(C * G, 1);U_tf = feedback(C, G);%% --- Simulação ---t      = linspace(0, tau*8, 5000);degrau = 40 - 25;[y, t] = step(T_mf * degrau, t);[u, ~] = step(U_tf * degrau, t);y_abs = y + 25;u_abs = u + 30;%% --- Métricas ---info = stepinfo(T_mf, 'SettlingTimeThreshold', 0.02);fprintf('Overshoot:        %.2f%%\n',   info.Overshoot)fprintf('Tempo de subida:  %.1f s  (%.1f min)\n', info.RiseTime,    info.RiseTime/60)fprintf('Tempo de acomod.: %.1f s  (%.1f min)\n', info.SettlingTime, info.SettlingTime/60)fprintf('Pico do controle: %.2f%%PWM\n', max(u_abs))%% --- Plot ---figuresubplot(2,1,1)plot(t/60, y_abs, 'b', 'LineWidth', 2)yline(40, 'r--', '40°C', 'LineWidth', 1.5)yline(25, 'k:',  '25°C', 'LineWidth', 1)ylabel('Temperatura (°C)'); xlabel('Tempo (min)')title(sprintf('PI-IMC  |  Kp=%.2f  |  Ti=%.0fs  |  lambda=%.0fs', Kp, Ti, lambda))grid onsubplot(2,1,2)plot(t/60, u_abs, 'r', 'LineWidth', 2)yline(100, 'k--', 'Saturação 100%', 'LineWidth', 1.5)yline(0,   'k:',  'Mínimo 0%',      'LineWidth', 1)ylabel('Sinal de controle (%PWM)'); xlabel('Tempo (min)')title(sprintf('Pico de controle: %.1f%%PWM', max(u_abs)))grid on; ylim([-5 110])